# Aurora Bento Grid — default.tsx
A visually dynamic grid layout featuring animated gradient backgrounds and interactive hover effects. Ideal for showcasing features, services, or dashboard modules with flair and clarity.

install: npx shadcn@latest add "https://21st.dev/r/dhileepkumargm/aurora-bento-grid?api_key=$API_KEY_21ST"

## Component
```tsx
import React from 'react';
import { motion } from 'framer-motion';

/**
 * A component for rendering an animated, multi-color aurora background.
 * Uses Framer Motion for smooth, continuous animation of gradient blobs.
 * @returns {JSX.Element} The rendered aurora background.
 */
export const AuroraBackground = () => {
  const Blob = ({ style, animateProps }) => (
    <motion.div
      className="absolute rounded-full mix-blend-hard-light filter blur-2xl opacity-40"
      style={style}
      animate={animateProps}
      transition={{
        duration: 25,
        repeat: Infinity,
        repeatType: 'reverse',
        ease: 'easeInOut',
      }}
    />
  );

  return (
    <div className="absolute inset-0 z-0 overflow-hidden">
      <Blob
        style={{
          top: '-20%',
          left: '-10%',
          width: '40rem',
          height: '40rem',
          background: 'rgba(192, 132, 252, 0.6)',
        }}
        animateProps={{ x: [0, 100, -50, 0], y: [0, -80, 120, 0] }}
      />
      <Blob
        style={{
          top: '20%',
          right: '-20%',
          width: '30rem',
          height: '30rem',
          background: 'rgba(250, 204, 21, 0.5)',
        }}
        animateProps={{ x: [0, -120, 70, 0], y: [0, 100, -90, 0] }}
      />
      <Blob
        style={{
          bottom: '-20%',
          left: '20%',
          width: '35rem',
          height: '35rem',
          background: 'rgba(59, 130, 246, 0.4)',
        }}
        animateProps={{ x: [0, 80, -110, 0], y: [0, -100, 60, 0] }}
      />
    </div>
  );
};

/**
 * A reusable container for the Bento Grid layout.
 * @param {object} props
 * @param {React.ReactNode} props.children
 * @returns {JSX.Element} The rendered Bento Grid container.
 */
export const BentoGrid = ({ children }) => {
  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: { staggerChildren: 0.1 },
    },
  };

  return (
    <motion.div
      variants={containerVariants}
      initial="hidden"
      animate="visible"
      className="grid grid-cols-1 md:grid-cols-6 gap-6 auto-rows-[280px] p-6"
    >
      {children}
    </motion.div>
  );
};

/**
 * A single item within the Bento Grid with hover and animation.
 * @param {object} props
 * @param {string} props.className
 * @param {React.ReactNode} props.children
 * @param {string} props.gradientFrom
 * @param {string} props.gradientTo
 * @returns {JSX.Element} The rendered grid item.
 */
export const BentoGridItem = ({
  className,
  children,
  gradientFrom,
  gradientTo,
}) => {
  const itemVariants = {
    hidden: { opacity: 0, y: 20 },
    visible: {
      opacity: 1,
      y: 0,
      transition: { duration: 0.5, ease: 'easeOut' },
    },
  };

  return (
    <motion.div
      variants={itemVariants}
      whileHover={{ scale: 1.03, transition: { duration: 0.2 } }}
      className={`
        relative overflow-hidden group
        bg-gradient-to-br ${gradientFrom} ${gradientTo}
        rounded-2xl shadow-lg p-6 flex flex-col justify-between
        ${className}
      `}
    >
      {/* Shine effect on hover */}
      <div
        className="
          absolute top-0 left-[-150%] h-full w-[50%]
          bg-[linear-gradient(to_right,transparent_0%,#ffffff33_50%,transparent_100%)]
          skew-x-[-25deg]
          transition-all duration-700 ease-in-out
          group-hover:left-[125%]
        "
      />
      <div className="relative z-10 h-full flex flex-col">
        {children}
      </div>
    </motion.div>
  );
};

```

## Demo (usage)
```tsx
import React from 'react';
import {
  AuroraBackground,
  BentoGrid,
  BentoGridItem,
} from '@/components/ui/aurora-bento-grid';
import {
  Briefcase,
  BarChart,
  Bell,
  Lock,
  Users,
  ArrowRight,
} from 'lucide-react';

/**
 * Main App component to demonstrate the colorful and animated Bento Grid.
 * @returns {JSX.Element} The rendered app with the Bento Grid.
 */
export default function DemoOne() {
  const features = [
    {
      icon: <Briefcase className="w-10 h-10 text-white" />,
      title: 'Project Management',
      description:
        'Organize tasks, deadlines, and team collaboration seamlessly.',
      className: 'md:col-span-4',
      gradientFrom: 'from-blue-500',
      gradientTo: 'to-cyan-400',
    },
    {
      icon: <BarChart className="w-10 h-10 text-white" />,
      title: 'Advanced Analytics',
      description:
        'Gain deep insights with our powerful data visualization tools.',
      className: 'md:col-span-2',
      gradientFrom: 'from-green-500',
      gradientTo: 'to-emerald-400',
    },
    {
      icon: <Bell className="w-10 h-10 text-white" />,
      title: 'Smart Notifications',
      description:
        'Stay updated with intelligent, context-aware alerts.',
      className: 'md:col-span-2',
      gradientFrom: 'from-yellow-500',
      gradientTo: 'to-amber-400',
    },
    {
      icon: <Users className="w-10 h-10 text-white" />,
      title: 'Team Collaboration',
      description:
        'Work together in real-time with shared spaces.',
      className: 'md:col-span-2',
      gradientFrom: 'from-purple-500',
      gradientTo: 'to-violet-400',
    },
    {
      icon: <Lock className="w-10 h-10 text-white" />,
      title: 'Enterprise-Grade Security',
      description:
        'Your data is protected with end-to-end encryption.',
      className: 'md:col-span-2',
      gradientFrom: 'from-red-500',
      gradientTo: 'to-orange-400',
    },
  ];

  return (
    <div className="min-h-screen w-full bg-gray-950 font-sans antialiased relative">
      <AuroraBackground />

      <div className="relative z-10 container mx-auto px-4 py-12">
        <div className="text-center mb-12">
          <h1
            className="
              text-4xl md:text-6xl font-extrabold tracking-tight
              bg-gradient-to-r from-pink-400 via-purple-400 to-indigo-500
              bg-clip-text text-transparent
            "
          >
            Features That Inspire
          </h1>
          <p className="mt-4 text-lg text-gray-300">
            Discover a new way to work and collaborate.
          </p>
        </div>

        <BentoGrid>
          {features.map((feature, i) => (
            <BentoGridItem
              key={i}
              className={feature.className}
              gradientFrom={feature.gradientFrom}
              gradientTo={feature.gradientTo}
            >
              <div className="mb-4">{feature.icon}</div>
              <div className="flex flex-col flex-grow">
                <h3 className="text-xl font-bold text-white mb-2">
                  {feature.title}
                </h3>
                <p className="text-gray-200 text-sm flex-grow">
                  {feature.description}
                </p>
              </div>
              <div className="mt-4">
                <a
                  href="#"
                  className="
                    text-white font-semibold text-sm inline-flex items-center
                    group
                  "
                >
                  Learn more
                  <ArrowRight className="ml-1 w-4 h-4 transition-transform duration-300 group-hover:translate-x-1" />
                </a>
              </div>
            </BentoGridItem>
          ))}
        </BentoGrid>
      </div>
    </div>
  );
}

